INSERT INTO campus_faqs (id, category, question, keywords, where_text, duration_text, steps_text, tip, sort_order) VALUES
(1,'请假','请假流程怎么走？','请假 流程 怎么请 去哪办 步骤 请假条','线上：「校园事务一站通」模拟门户 → 学生事务 → 请假申请；线下：示例学院学生工作办公室（模拟）','线上填表约 3 分钟；辅导员审批 1 个工作日内；超过 3 天需学院加签，约 2 个工作日','发起申请~校园事务一站通（模拟）→ 学生事务 → 请假申请~学号、请假类型、起止时间、事由~约 3 分钟;;辅导员审批~示例学院学生工作办公室（模拟），系统自动推送待办~病假附校医院（模拟）诊断证明照片；事假写清事由~1 个工作日内;;加签与销假~3 天以上由学院分管负责人（模拟）线上加签；返校后回原入口点销假~加签意见、实际返校日期~加签约 2 个工作日；销假 1 分钟','示例：同学A 请病假 2 天只走前两步；同学B 请公假 5 天需加签。',1),
(2,'请假','病假需要哪些材料？','病假 材料 诊断证明 校医院 病历','校医院（模拟）开诊断证明 → 校园事务一站通（模拟）上传 → 辅导员（模拟）审批','开证明约 15 分钟，上传 2 分钟，审批 1 个工作日内','开诊断证明~校医院（模拟）门诊服务台~校园卡（模拟）、就诊记录~约 15 分钟;;上传附件~校园事务一站通（模拟）→ 请假申请 → 上传附件~诊断证明清晰照片、请假起止时间~约 2 分钟;;补交与归档~示例学院学生工作办公室（模拟）~急诊等特殊情况可先请假、返校后 3 日内补交证明~补交 1 个工作日；归档即时','示例：同学C 曾上传挂号截图被退回，请务必上传正式诊断证明（模拟）。',2),
(3,'请假','请假超过三天怎么审批？','请假 三天 超过 长期 加签 审批','校园事务一站通（模拟）→ 请假申请 → 学院加签；必要时到示例学院学生工作办公室（模拟）面签','辅导员 1 个工作日 + 学院加签 2 个工作日，合计约 3 个工作日','提交长时申请~校园事务一站通（模拟）→ 请假申请，勾选「超过 3 天」~事由说明、课程受影响清单、家长知情确认（模拟）~约 5 分钟;;辅导员初审~示例学院学生工作办公室（模拟）~课程任课教师（模拟）知情意见~1 个工作日;;学院加签~学院分管负责人（模拟）线上审批~初审意见、离校与返校安排~约 2 个工作日','建议至少提前 3 个工作日发起；示例：同学A 的 7 天公假在第 3 个工作日办结。',3),
(4,'报修','宿舍水电坏了怎么报修？','报修 宿舍 水电 灯 漏水 后勤','「后勤服务平台」（模拟）→ 宿舍报修；紧急漏水可到本楼宿管值班室（模拟）登记','提交 2 分钟；一般 1 个工作日内上门；紧急件 2 小时内响应','提交报修单~后勤服务平台（模拟）→ 宿舍报修~楼栋、房间号、故障描述、可上门时间段、现场照片~约 2 分钟;;派单与联系~后勤维修班组（模拟）接单后电话/站内信联系~保持电话畅通，宿舍留人~一般 1 个工作日内；紧急件 2 小时内;;验收与评价~后勤服务平台（模拟）→ 我的报修 → 确认完成~现场核对维修结果、拍照~约 1 分钟','示例：同学B 报修灯管，填了房间号和照片，当天完成。',4),
(5,'报修','教室多媒体设备报修找谁？','报修 教室 投影 多媒体 设备 上课','教学楼一层值班室（模拟）现场登记，或「教务服务门户」（模拟）→ 教室设备报修','现场登记 3 分钟；课前紧急件 15 分钟内到场，常规件 1 个工作日','现场处置~明德楼一层教学值班室（模拟）~教室编号、课程时段、故障现象~课前紧急件约 15 分钟到场;;线上补单~教务服务门户（模拟）→ 教室设备报修~现场登记编号、设备照片~约 3 分钟;;结果反馈~教务服务门户（模拟）→ 我的报修~确认设备恢复，必要时申请临时调课~常规件 1 个工作日内','上课前发现故障优先去值班室，别只等线上工单。',5),
(6,'报修','报修后多久来修、怎么催单？','报修 进度 催单 多久 超时 查询','后勤服务平台（模拟）→ 我的报修 查进度；超时可到校园事务服务中心（模拟）窗口催办','查进度即时；一般件 1 个工作日，超时催办后 4 小时内响应','查进度~后勤服务平台（模拟）→ 我的报修 → 工单详情~报修单号~即时;;一键催单~工单详情页点「催办」，或拨打后勤服务热线（模拟）~单号、超期时长、影响说明~约 1 分钟，4 小时内响应;;窗口协调~明德楼一层校园事务服务中心（模拟）综合窗口~校园卡（模拟）、工单截图~现场约 10 分钟','示例：同学C 的水管工单超期，催办后当天修复。',6),
(7,'证明开具','在读证明去哪开？','在读证明 学籍证明 去哪开 盖章 自助打印','明德楼一层自助服务机（模拟）自助打印，或「教务服务门户」（模拟）→ 证明开具申请电子版','自助打印 2 分钟；电子版即时生成；人工窗口 10 分钟','选择用途版本~教务服务门户（模拟）→ 证明开具 → 在读证明~用途（如奖助申请、考试报名）、是否需要盖章版~约 1 分钟;;自助打印或下载~明德楼一层自助服务机（模拟）刷校园卡打印；线上可下载带电子章 PDF（模拟）~校园卡（模拟）、学号~约 2 分钟;;人工盖章（如需）~明德楼一层校园事务服务中心（模拟）教务窗口~打印件、用途说明~约 10 分钟','多数场景电子章版即可；示例：同学A 用电子版完成奖助申请。',7),
(8,'证明开具','成绩单怎么申请？','成绩单 中英文 打印 申请 盖章','教务服务门户（模拟）→ 证明开具 → 成绩单；中英文版到教务窗口（模拟）办理','中文版自助打印 2 分钟；中英文版 1 个工作日','核对成绩~教务服务门户（模拟）→ 我的成绩~学号、需覆盖的学期范围~约 2 分钟;;申请成绩单~教务服务门户（模拟）→ 证明开具；中英文版到明德楼教务窗口（模拟）~用途、份数；中英文版需注明~中文版即时；中英文版 1 个工作日;;领取与核验~自助服务机打印或教务窗口领取~校园卡（模拟）、申请单号~约 3 分钟','中英文版需翻译校对，别卡在截止日当天才申请。',8),
(9,'证明开具','学生证遗失怎么补办？','学生证 遗失 补办 挂失 证明','校园事务一站通（模拟）→ 学生事务 → 证件补办；领取在校园卡中心（模拟）','挂失即时，线上申请 3 分钟，制证 3 个工作日','先挂失~校园事务一站通（模拟）→ 证件挂失~学号、遗失说明~即时;;提交补办~校园事务一站通（模拟）→ 学生事务 → 证件补办~证件照电子版（模拟）、工本费（模拟）~约 3 分钟;;领取新证~明德楼一层校园卡中心（模拟）~校园卡（模拟）、申请单号~制证 3 个工作日；领取 5 分钟','等待期间可在同一入口开「在读证明」临时替代；示例：同学B 用过。',9),
(10,'报销','报销要哪些材料？','报销 材料 发票 清单 需要什么','「财务服务门户」（模拟）→ 网上报销；纸质件交明德楼二层财务窗口（模拟）','线上填单约 8 分钟；审核 3 个工作日；到账 5 个工作日','备齐材料~自行整理，或参考财务服务门户（模拟）材料清单~合规发票（模拟）、明细清单、事由说明、审批单、收款信息~约 10 分钟;;网上填单~财务服务门户（模拟）→ 网上报销 → 新建报销单~发票信息、金额、项目/活动名称、附件照片~约 8 分钟;;交件与审核~明德楼二层财务窗口（模拟）投递纸质件~报销单号、按清单顺序装订的原件~交件 5 分钟；审核 3 个工作日','发票抬头、税号以门户示例为准；缺明细清单是最常见的退单原因。',10),
(11,'报销','社团活动经费怎么报销？','报销 社团 活动经费 预算 审批','云帆社团联合会（模拟）初审 → 财务服务门户（模拟）→ 网上报销','预算备案 1 个工作日；报销审核 3 个工作日；合计约 1 周','活动前预算备案~云帆社团联合会（模拟）线上备案~活动方案、预算明细、负责人（同学A/B/C 代称）~1 个工作日;;活动后归集票据~财务服务门户（模拟）→ 网上报销 → 社团经费~发票（模拟）、活动签到表、总结、备案编号~约 10 分钟;;两级审核~社团联合会（模拟）初审 → 财务窗口（模拟）复审~报销单号、纸质原件~约 3 个工作日','先备案后花钱，没备案的活动经费通常不予报销。',11),
(12,'报销','报销多久到账、被退回怎么办？','报销 到账 退回 进度 多久 查询','财务服务门户（模拟）→ 我的报销 查状态；退单在明德楼二层财务窗口（模拟）咨询','审核通过后 5 个工作日到账；退单修改重提约 15 分钟','查状态~财务服务门户（模拟）→ 我的报销~报销单号~即时;;按意见修改~原报销单点「退回修改」，或到财务窗口（模拟）~退单原因截图、补正材料~约 15 分钟;;到账核对~财务服务门户（模拟）→ 到账记录，或绑定的银行卡（模拟）~单号、金额~审核通过后 5 个工作日','示例：同学C 因缺明细清单被退回，补齐后 3 个工作日审核通过。',12),
(13,'选课','选课在哪选、什么时候开始？','选课 时间 入口 教务系统 预选 正选','「教务服务门户」（模拟）→ 选课中心；通知在门户首页「选课公告」（模拟）','预选 3 天、正选 2 天；单次操作约 5 分钟','看公告与核对培养方案~教务服务门户（模拟）→ 选课公告 / 我的培养方案~学号、本专业应修学分清单~约 10 分钟;;预选~教务服务门户（模拟）→ 选课中心 → 预选~课程代码、备选课程清单~开放 3 天，操作约 5 分钟;;正选与确认课表~教务服务门户（模拟）→ 选课中心 → 正选 / 我的课表~预选结果、冲突检查~开放 2 天，确认 2 分钟','选课开放时间以模拟公告为准，正选先到先得，建议定好提醒。',13),
(14,'选课','选课满了或时间冲突怎么办？','选课 满员 冲突 抢课 候补 改选','教务服务门户（模拟）→ 选课中心 → 候补/冲突申诉；学院教务员（模拟）处理特殊冲突','候补登记 2 分钟；候补结果 1 个工作日；申诉 2 个工作日','登记候补~教务服务门户（模拟）→ 选课中心 → 候补名单~课程代码、候补顺序确认~约 2 分钟；1 个工作日出结果;;换备选课~教务服务门户（模拟）→ 选课中心 → 改选~同类别备选课程代码、课表空档~约 5 分钟;;冲突申诉~示例学院教务办公室（模拟）或门户「冲突申诉」~课表截图、必修课证明~约 2 个工作日','必修课冲突优先走申诉；示例：同学A 的必修冲突 2 个工作日解决。',14),
(15,'选课','退选和改选怎么操作？','退选 改选 退课 选课 截止 学分','教务服务门户（模拟）→ 选课中心 → 退选/改选（仅在开放期内）','线上操作 2 分钟；生效即时；开放期一般为开课后 2 周内','确认开放期~教务服务门户（模拟）→ 选课公告~学期、退改选截止日期~约 1 分钟;;提交退改选~教务服务门户（模拟）→ 选课中心 → 退选/改选~课程代码、退选后学分是否达标~约 2 分钟，即时生效;;核对课表与学分~教务服务门户（模拟）→ 我的课表 / 我的培养方案~最新课表、学分统计~约 2 分钟','退选后别低于最低学分要求；逾期需到学院教务办公室（模拟）申请特殊处理。',15),
(16,'补考','补考怎么报名？','补考 报名 挂科 重修 入口','教务服务门户（模拟）→ 考试管理 → 补考报名；名单见门户「补考安排」（模拟）','报名 3 分钟；名单发布 2 个工作日；考试一般在开学后第 2 周','确认资格与科目~教务服务门户（模拟）→ 我的成绩 / 补考安排~学号、需补考科目代码~约 3 分钟;;线上报名~教务服务门户（模拟）→ 考试管理 → 补考报名~科目、联系方式（模拟）~约 3 分钟;;查看考场~教务服务门户（模拟）→ 考试管理 → 我的考场~校园卡（模拟）、考试时间段~考前 1 天发布','未报名不能参加补考；示例：同学B 漏报名，只能等下一轮。',16),
(17,'补考','缓考和补考有什么区别？','缓考 补考 区别 申请 因病','缓考：教务服务门户（模拟）→ 考试管理 → 缓考申请；补考：同门户 → 补考报名','缓考申请需在考前提交，审批 1 个工作日；补考按学期统一安排','判断适用情形~教务服务门户（模拟）→ 考试管理规定~因病/突发事由属缓考；已缺考或不及格属补考~约 3 分钟;;考前提交缓考~教务服务门户（模拟）→ 考试管理 → 缓考申请~校医院（模拟）证明或事由说明、课程代码~约 5 分钟；审批 1 个工作日;;按安排参加考试~教务服务门户（模拟）→ 我的考场~校园卡（模拟）、缓考批准记录~随下一学期补考安排，约第 2 周','缓考按首次考试记成绩，补考按补考规则记载，别搞反。',17),
(18,'补考','补考成绩什么时候出、怎么记？','补考 成绩 记载 绩点 出来 查询','教务服务门户（模拟）→ 我的成绩；异议到示例学院教务办公室（模拟）','考后 5 个工作日发布；复核申请 3 个工作日','查成绩~教务服务门户（模拟）→ 我的成绩 → 补考成绩~学号、科目代码~考后约 5 个工作日;;核对记载规则~教务服务门户（模拟）→ 学籍管理规定~成绩单、绩点计算说明~约 5 分钟;;申请复核~示例学院教务办公室（模拟）或门户「成绩复核」~复核申请、科目与考场信息~约 3 个工作日','示例：同学C 复核后发现登分误差，3 个工作日内更正。',18),
(19,'宿舍','宿舍调寝怎么申请？','宿舍 调寝 换寝室 申请 床位','「后勤服务平台」（模拟）→ 住宿服务 → 调寝申请；线下到本楼宿管值班室（模拟）','线上申请 5 分钟；宿管与学院两级审核共 3 个工作日','确认空床位~后勤服务平台（模拟）→ 住宿服务 → 床位查询~目标楼栋、房间号、原床位~约 2 分钟;;提交申请~后勤服务平台（模拟）→ 调寝申请~调寝事由、双方室友确认（模拟）、辅导员意见~约 5 分钟;;审核与搬迁~本楼宿管值班室（模拟）办理钥匙与物品交接~校园卡（模拟）、申请单号、原钥匙~审核 3 个工作日；交接 20 分钟','需原室友与目标室友确认；示例：同学A 的申请因缺确认被退回一次。',19),
(20,'宿舍','晚归或门禁异常怎么登记？','宿舍 晚归 门禁 登记 刷不开','本楼宿管值班室（模拟）现场登记；门禁异常在后勤服务平台（模拟）→ 门禁报障','现场登记 3 分钟；门禁权限修复 1 个工作日内','现场说明登记~本楼宿管值班室（模拟）~校园卡（模拟）、晚归事由、返回时间~约 3 分钟;;情况报备~示例学院学生工作办公室（模拟），由宿管同步~登记记录编号~1 个工作日内同步;;门禁权限修复~后勤服务平台（模拟）→ 门禁报障 / 校园卡中心（模拟）~卡号（模拟）、故障楼栋~约 1 个工作日','晚归当晚登记，别攒到月底；示例：同学B 当晚登记即完成。',20),
(21,'宿舍','假期留宿和退宿怎么办理？','宿舍 假期留宿 退宿 离校 申请','后勤服务平台（模拟）→ 住宿服务 → 假期留宿 / 退宿申请；退宿到本楼宿管值班室（模拟）验房','留宿申请 5 分钟，审批 2 个工作日；退宿验房约 20 分钟','提交留宿申请~后勤服务平台（模拟）→ 假期留宿~留宿起止日期、事由、紧急联系人（模拟）~约 5 分钟；审批 2 个工作日;;假期管理确认~本楼宿管值班室（模拟）~批准记录、留宿期间门禁授权~约 10 分钟;;退宿验房~本楼宿管值班室（模拟）现场验房~钥匙、水电结算单（模拟）、个人物品清退~约 20 分钟','毕业/交换离校需先退宿再办离校手续；示例：同学C 按此顺序一次办完。',21),
(22,'校园卡','校园卡丢了怎么挂失补办？','校园卡 丢失 挂失 补卡 一卡通','「校园卡服务」小程序（模拟）即时挂失；补卡在明德楼一层校园卡中心（模拟）','挂失即时，补卡申请 3 分钟，制卡 1 个工作日','立即挂失~校园卡服务（模拟）→ 挂失，或校园卡中心（模拟）窗口~学号、支付密码（模拟）~即时，先做这步止损;;申请补卡~校园卡服务（模拟）→ 补卡申请 / 校园卡中心（模拟）~证件照（模拟）、工本费（模拟）~约 3 分钟;;领卡与余额转移~明德楼一层校园卡中心（模拟）~校园卡（模拟）或身份证件、申请单号~制卡 1 个工作日；领卡 5 分钟，余额自动转移','示例：同学A 10 分钟内挂失，余额未受损。',22),
(23,'校园卡','校园卡在哪充值？','校园卡 充值 余额 缴费 在哪','校园卡服务（模拟）在线充值；明德楼一层与各食堂（模拟）圈存机','在线充值即时到账；圈存机约 1 分钟','在线充值~校园卡服务（模拟）→ 充值~学号、支付方式（模拟）~即时到账;;圈存补登~明德楼一层 / 各食堂圈存机（模拟）~校园卡（模拟）~约 1 分钟，把在线金额写入卡;;核对余额~校园卡服务（模拟）→ 余额查询~卡号（模拟）~即时','在线充值后如刷卡仍显示旧余额，去圈存机补登一次即可。',23),
(24,'校园卡','消费记录怎么查、扣错钱怎么办？','校园卡 消费记录 扣错 多扣 退款 申诉','校园卡服务（模拟）→ 流水查询 / 异常申诉；窗口在明德楼一层校园卡中心（模拟）','查流水即时；申诉审核 2 个工作日，退款 1 个工作日','查流水~校园卡服务（模拟）→ 流水查询~时间段、商户名称（模拟）~即时;;提交异常申诉~校园卡服务（模拟）→ 异常申诉，或校园卡中心（模拟）窗口~流水截图、时间金额、说明~约 5 分钟；审核 2 个工作日;;退款核对~校园卡服务（模拟）→ 余额查询~申诉单号~审核通过后 1 个工作日到账','示例：同学C 的重复扣款申诉后 2 个工作日退回。',24),
(25,'图书馆','借书、续借和借阅上限是怎样的？','图书馆 借书 续借 上限 借阅规则','图书馆服务台（模拟）或「图书馆门户」（模拟）→ 我的借阅','借书 2 分钟；续借即时；借期 30 天（模拟）','检索与借书~图书馆门户（模拟）→ 馆藏检索 → 自助借书机（模拟）~校园卡（模拟）、索书号~约 2 分钟；上限 10 册（模拟）;;线上续借~图书馆门户（模拟）→ 我的借阅 → 续借~无他人预约的可续借 1 次~即时，续 30 天（模拟）;;查看到期提醒~图书馆门户（模拟）→ 我的借阅~到期日清单~即时','被预约的图书不能续借；示例：同学A 设了到期提醒，从未逾期。',25),
(26,'图书馆','图书逾期或遗失怎么处理？','图书馆 逾期 遗失 赔偿 罚款 处理','图书馆一层服务台（模拟）或图书馆门户（模拟）→ 违章处理','线上处理 3 分钟；现场核验约 10 分钟','查违章记录~图书馆门户（模拟）→ 我的借阅 → 违章记录~学号、书名~即时;;归还或说明~图书馆一层服务台（模拟）~逾期图书；遗失需说明情况~约 10 分钟;;缴纳费用/赔偿~图书馆门户（模拟）→ 违章处理，或服务台（模拟）~违章单号、校园卡（模拟）~约 3 分钟，处理后借阅权限即时恢复','示例：同学B 遗失图书后按同版新书赔偿，当天恢复借阅。',26),
(27,'图书馆','研讨间和座位怎么预约？','图书馆 研讨间 座位 预约 自习','图书馆门户（模拟）→ 空间预约；现场在各楼层选位机（模拟）','预约 2 分钟；可提前 3 天预约（模拟），单次 2 小时','选时段与空间~图书馆门户（模拟）→ 空间预约~使用人数、时段、研讨间编号~约 2 分钟;;签到使用~研讨间门口签到机（模拟）刷校园卡~校园卡（模拟）、预约码~开场 15 分钟内签到，约 1 分钟;;取消或改约~图书馆门户（模拟）→ 我的预约~预约单号~即时；爽约 2 次暂停预约 7 天（模拟）','示例：同学C 的小组讨论提前 3 天约到研讨间。',27),
(28,'社团','怎么加入社团、在哪看名单？','社团 加入 报名 名单 招新','「云帆社团联合会」门户（模拟）→ 社团名录 / 招新报名；线下招新在明德广场（模拟）','浏览名录 5 分钟；线上报名 3 分钟；录取通知 3 个工作日','查社团名录~云帆社团联合会（模拟）→ 社团名录~兴趣方向、可参与时段~约 5 分钟;;线上报名~云帆社团联合会（模拟）→ 招新报名~学号、意向社团、简短自我介绍（同学A/B/C 代称）~约 3 分钟;;面试/录取与确认~各社团活动室（模拟）或站内通知~报名编号、作品或特长说明（如需）~3 个工作日内出结果','每人最多报 3 个社团（模拟）；示例：同学A 报了 2 个。',28),
(29,'社团','社团活动场地怎么申请？','社团 场地 申请 教室 活动 借用','云帆社团联合会（模拟）→ 场地申请；教室类需教务服务门户（模拟）复核','提交 5 分钟；审核 2 个工作日；建议提前 5 个工作日申请','查可用场地~云帆社团联合会（模拟）→ 场地日历~活动日期、时段、预计人数、设备需求~约 3 分钟;;提交申请~云帆社团联合会（模拟）→ 场地申请~活动方案、安全预案（模拟）、负责人信息~约 5 分钟；审核 2 个工作日;;领取与归还~场地管理值班室（模拟）~批准单、校园卡（模拟）；使用后现场验收~领钥匙 5 分钟；归还验收 10 分钟','示例：同学B 的分享会提前 5 个工作日申请，一次通过。',29),
(30,'社团','新社团怎么申请成立？','社团 成立 注册 新社团 申请 指导老师','云帆社团联合会（模拟）→ 社团成立申请；材料交明德楼三层社团事务窗口（模拟）','材料准备约 1 周；初审 5 个工作日；答辩与公示 5 个工作日','组建发起团队~校内自行发起，名单用同学A/B/C 等代称登记~发起人 5 人以上（模拟）、指导老师（模拟）意向、社团章程草案~约 1 周;;提交成立材料~云帆社团联合会（模拟）→ 社团成立申请，纸质件交社团事务窗口（模拟）~章程、发起人名单、年度活动计划、指导老师确认函（模拟）~提交 15 分钟；初审 5 个工作日;;答辩与公示~云帆社团联合会（模拟）会议室 / 门户公示栏~答辩材料、修订后的章程~答辩 20 分钟；公示 5 个工作日','成立前不得以社团名义申请经费；示例：同学C 团队在第 3 周完成公示。',30)